+/*
+** This function is used to parse filenames passed by the user to API
+** functions sqlite3_open() or sqlite3_open_v2(), and for database filenames
+** specified as part of ATTACH statements.
+*/
+int sqlite3ParseUri(
+  const char *zDefaultVfs,        /* VFS to use if no "vfs=xxx" query option */
+  const char *zUri,               /* Nul-terminated URI to parse */
+  int *pFlags,                    /* IN/OUT: SQLITE_OPEN_XXX flags */
+  sqlite3_vfs **ppVfs,            /* OUT: VFS to use */ 
+  char **pzFile,                  /* OUT: Filename component of URI */
+  char **pzErrMsg                 /* OUT: Error message (if rc!=SQLITE_OK) */
+){
+  int flags = *pFlags;
+  const char *zVfs = zDefaultVfs;
+  char *zFile;
+  i64 nUri = strlen(zUri);
+
+  assert( *pzErrMsg==0 );
+
+  /* The allocator in this version accepts only int-sized requests. */
+  if( nUri>=0x7fffff00-2 ) return SQLITE_NOMEM;
+
+  if( ((flags & SQLITE_OPEN_URI) || sqlite3GlobalConfig.bOpenUri) 
+   && nUri>=5 && memcmp(zUri, "file:", 5)==0 
+  ){
+    char *zOpt = 0;
+    int eState;                   /* Parser state when parsing URI */
+    i64 iIn;                      /* Input character index */
+    i64 iOut = 0;                 /* Output character index */
+    u64 nByte = nUri+2;           /* Bytes of space to allocate */
+    for(iIn=0; iIn<nUri; iIn++) nByte += (zUri[iIn]=='&');
+
+    if( nByte>=0x7fffff00 ) return SQLITE_NOMEM;
+    zFile = sqlite3_malloc((int)nByte);
+    if( !zFile ) return SQLITE_NOMEM;
+
+    /* Discard the scheme and authority segments of the URI. */
+    if( zUri[5]=='/' && zUri[6]=='/' ){
+      iIn = 7;
+      while( zUri[iIn] && zUri[iIn]!='/' ) iIn++;
+    }else{
+      iIn = 5;
+    }
+
+    /* Copy the filename and any query parameters into the zFile buffer. 
+    ** Decode %HH escape codes along the way. 
+    **
+    ** Within this loop, variable eState may be set to 0, 1 or 2, depending
+    ** on the parsing context. As follows:
+    **
+    **   0: Parsing file-name.
+    **   1: Parsing name section of a name=value query parameter.
+    **   2: Parsing value section of a name=value query parameter.
+    */
+    eState = 0;
+    while( zUri[iIn] && zUri[iIn]!='#' ){
+      char c = zUri[iIn++];
+      if( c=='%' 
+       && sqlite3Isxdigit(zUri[iIn]) 
+       && sqlite3Isxdigit(zUri[iIn+1]) 
+      ){
+        int codepoint = (sqlite3HexToInt(zUri[iIn++]) << 4);
+        codepoint += sqlite3HexToInt(zUri[iIn++]);
+
+        assert( codepoint>=0 && codepoint<256 );
+        if( codepoint==0 ) continue;
+        c = codepoint;
+      }else if( (eState==0 && c=='?') || (eState==1 && c=='=') ){
+        if( eState==0 ){
+          zOpt = &zFile[iOut+1];
+        }
+        eState++;
+        c = 0;
+      }else if( eState!=0 && c=='&' ){
+        if( eState==1 ) zFile[iOut++] = '\0';
+        eState = 1;
+        c = 0;
+      }
+      zFile[iOut++] = c;
+    }
+    if( eState==1 ) zFile[iOut++] = '\0';
+    zFile[iOut++] = '\0';
+    zFile[iOut++] = '\0';
+
+    /* Check if there were any options specified that should be interpreted 
+    ** here. Options that are interpreted here include "vfs" and those that
+    ** correspond to flags that may be passed to the sqlite3_open_v2()
+    ** method.  */
+    if( zOpt ){
+      struct Option {
+        const char *zOption;
+        int mask;
+      } aOpt [] = {
+        { "vfs", 0 },
+        { "readonly",     SQLITE_OPEN_READONLY },
+        { "readwrite",    SQLITE_OPEN_READWRITE },
+        { "create",       SQLITE_OPEN_CREATE },
+        { "sharedcache",  SQLITE_OPEN_SHAREDCACHE },
+        { "privatecache", SQLITE_OPEN_PRIVATECACHE }
+      };
+
+      while( zOpt[0] ){
+        i64 nOpt = strlen(zOpt);
+        char *zVal = &zOpt[nOpt+1];
+        i64 nVal = strlen(zVal);
+        int i;
+
+        for(i=0; i<ArraySize(aOpt); i++){
+          const char *z = aOpt[i].zOption;
+          if( nOpt==(i64)strlen(z) && 0==memcmp(zOpt, z, nOpt) ){
+            int mask = aOpt[i].mask;
+            if( mask==0 ){
+              zVfs = zVal;
+            }else{
+              if( zVal[0]=='\0' || sqlite3GetBoolean(zVal) ){
+                flags |= mask;
+              }else{
+                flags &= ~mask;
+              }
+            }
+          }
+        }
+
+        zOpt = &zVal[nVal+1];
+      }
+    }
+
+  }else{
+    zFile = sqlite3_malloc((int)(nUri+2));
+    if( !zFile ) return SQLITE_NOMEM;
+    memcpy(zFile, zUri, nUri);
+    zFile[nUri] = '\0';
+    zFile[nUri+1] = '\0';
+  }
+
+  *ppVfs = sqlite3_vfs_find(zVfs);
+  if( *ppVfs==0 ){
